```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg rst;
    wire out;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .out(out)
    );

    // Stimulus & self-checking:
    integer errors = 0;

    initial begin
        // Apply stimulus
        clk = 1'b0;
        rst = 1'b0;
        #10;

        // Test case 1: Check output is low when rst is low
        rst = 1'b0;
        clk = 1'b1;
        #10;
        if (out != 1'b0) begin
            errors = errors + 1;
        end

        // Test case 2: Check output is low when rst is high
        rst = 1'b1;
        clk = 1'b1;
        #10;
        if (out != 1'b0) begin
            errors = errors + 1;
        end

        // Test case 3: Check output is low when clk is high
        rst = 1'b0;
        clk = 1'b1;
        #10;
        if (out != 1'b0) begin
            errors = errors + 1;
        end

        // Test case 4: Check output is low when clk is low
        rst = 1'b0;
        clk = 1'b0;
        #10;
        if (out != 1'b0) begin
            errors = errors + 1;
        end

        // Print test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        // Terminate simulation
        $finish;
    end

    // Clock generation
    always begin
        #5 clk = ~clk;
    end

endmodule
```

